import { memoizeHash as simpleHash, rendererLogger as logger } from "../../../utils/index.js";
import { dirname, extname, join } from "../../../platform/compat/path/index.js";
import { LAYOUT_EXTENSIONS } from "../types.js";
import { LRUCache } from "../../../utils/lru-wrapper.js";
import { registerLRUCache } from "../../../cache/index.js";
const discoveryLog = logger.component("discovery");
const layoutLog = logger.component("layout");
const MAX_CACHE_SIZE = 500;
const legacyAdapterIds = new WeakMap();
let nextLegacyAdapterId = 1;
const layoutDiscoveryCache = new LRUCache({
    maxEntries: MAX_CACHE_SIZE,
});
// Register cache for monitoring and bulk clearing
registerLRUCache("layout-discovery-cache", layoutDiscoveryCache);
export function clearLayoutDiscoveryCache(projectDir) {
    if (!projectDir) {
        discoveryLog.debug("Clearing entire layout discovery cache", {
            size: layoutDiscoveryCache.size,
        });
        layoutDiscoveryCache.clear();
        return;
    }
    let cleared = 0;
    for (const key of [...layoutDiscoveryCache.keys()]) {
        const entry = layoutDiscoveryCache.get(key);
        if (entry && entry.projectDir === projectDir) {
            layoutDiscoveryCache.delete(key);
            cleared++;
        }
    }
    discoveryLog.debug("Cleared layout discovery cache for project", {
        projectDir,
        cleared,
        remaining: layoutDiscoveryCache.size,
    });
}
export function getLayoutDiscoveryCacheStats() {
    return { size: layoutDiscoveryCache.size, maxSize: MAX_CACHE_SIZE };
}
export async function discoverNestedLayouts(pageFilePath, rootDir, projectDir, adapter, identity) {
    // Production collectors pass project and source identities. Legacy direct
    // callers retain adapter-scoped caching for compatibility; mutable collectors
    // pass cache:false when no trustworthy snapshot identity is available.
    let legacyAdapterId;
    if (identity === undefined) {
        legacyAdapterId = legacyAdapterIds.get(adapter);
        if (legacyAdapterId === undefined) {
            legacyAdapterId = nextLegacyAdapterId++;
            legacyAdapterIds.set(adapter, legacyAdapterId);
        }
    }
    const key = identity?.cache === false
        ? null
        : identity?.projectId && identity.contentSourceId
            ? simpleHash(identity.projectId, identity.contentSourceId, projectDir, pageFilePath, rootDir)
            : identity === undefined
                ? simpleHash(`legacy-adapter-${legacyAdapterId}`, projectDir, pageFilePath, rootDir)
                : null;
    const cached = key ? layoutDiscoveryCache.get(key) : undefined;
    if (cached) {
        cached.accessedAt = Date.now();
        discoveryLog.debug("Layout cache HIT", {
            pageFilePath,
            rootDir,
            projectId: identity?.projectId,
            contentSourceId: identity?.contentSourceId,
            layoutCount: cached.layouts.length,
            layoutPaths: cached.layouts.map((l) => l.path),
        });
        return cached.layouts;
    }
    discoveryLog.debug("Layout cache MISS, discovering layouts", {
        pageFilePath,
        rootDir,
        projectDir,
        projectId: identity?.projectId,
        contentSourceId: identity?.contentSourceId,
    });
    const layouts = await discoverNestedLayoutsImpl(pageFilePath, rootDir, adapter);
    discoveryLog.debug("Found layouts", {
        pageFilePath,
        layoutCount: layouts.length,
        layoutPaths: layouts.map((l) => l.path),
    });
    if (key) {
        layoutDiscoveryCache.set(key, { layouts, accessedAt: Date.now(), projectDir });
    }
    return layouts;
}
async function discoverNestedLayoutsImpl(pageFilePath, rootDir, adapter) {
    const nestedLayouts = [];
    try {
        const candidates = collectLayoutCandidates(pageFilePath, rootDir);
        const existing = await resolveExistingFiles(candidates.reverse(), adapter);
        logger.debug("Found layout files:", existing);
        addLayoutsFromFiles(existing, nestedLayouts);
        await addMissedAncestorLayouts(pageFilePath, rootDir, existing, nestedLayouts, adapter);
    }
    catch (e) {
        logger.warn("Nested layout discovery failed", e);
    }
    return nestedLayouts;
}
function collectLayoutCandidates(pageFilePath, rootDir) {
    const candidates = [];
    let currentDir = dirname(pageFilePath);
    while (currentDir.startsWith(rootDir)) {
        for (const ext of LAYOUT_EXTENSIONS) {
            candidates.push(join(currentDir, `layout.${ext}`));
        }
        const parent = dirname(currentDir);
        if (parent === currentDir || currentDir === rootDir)
            break;
        currentDir = parent;
    }
    if (!candidates.includes(join(rootDir, "layout.mdx"))) {
        for (const ext of LAYOUT_EXTENSIONS) {
            candidates.push(join(rootDir, `layout.${ext}`));
        }
    }
    return candidates;
}
async function resolveExistingFiles(candidates, adapter) {
    const results = await Promise.allSettled(candidates.map((file) => adapter.fs.stat(file)));
    const existing = [];
    const seenDirs = new Set();
    for (let i = 0; i < results.length; i++) {
        const result = results[i];
        if (!result)
            continue;
        if (result.status === "fulfilled" && result.value.isFile) {
            const candidatePath = candidates[i];
            if (!candidatePath)
                continue;
            const dir = dirname(candidatePath);
            if (seenDirs.has(dir))
                continue;
            existing.push(candidatePath);
            seenDirs.add(dir);
            continue;
        }
        if (result.status === "rejected") {
            layoutLog.debug("stat layout candidate failed", result.reason);
        }
    }
    return existing;
}
function addLayoutsFromFiles(files, nestedLayouts) {
    for (const file of files) {
        const ext = extname(file).toLowerCase();
        if (ext === ".mdx" || ext === ".md") {
            nestedLayouts.push({ kind: "mdx", path: file });
            continue;
        }
        if (ext === ".tsx" || ext === ".jsx" || ext === ".ts" || ext === ".js") {
            logger.debug("Adding TSX layout:", file);
            nestedLayouts.push({
                kind: "tsx",
                component: undefined,
                componentPath: file,
                path: file,
            });
        }
    }
}
async function addMissedAncestorLayouts(pageFilePath, rootDir, existing, nestedLayouts, adapter) {
    try {
        const included = new Set(existing);
        const dirsWithLayouts = new Set(existing.map((p) => dirname(p)));
        const candidates = [];
        let dir = dirname(pageFilePath);
        while (dir.startsWith(rootDir)) {
            if (!dirsWithLayouts.has(dir)) {
                for (const ext of LAYOUT_EXTENSIONS) {
                    const candidate = join(dir, `layout.${ext}`);
                    if (!included.has(candidate))
                        candidates.push(candidate);
                }
            }
            const parent = dirname(dir);
            if (parent === dir)
                break;
            dir = parent;
        }
        const results = await Promise.allSettled(candidates.map((cand) => adapter.fs.stat(cand)));
        for (let i = 0; i < results.length; i++) {
            const result = results[i];
            const cand = candidates[i];
            if (!result || !cand)
                continue;
            if (result.status === "fulfilled" && result.value.isFile) {
                const candDir = dirname(cand);
                if (dirsWithLayouts.has(candDir))
                    continue;
                addLayoutsFromFiles([cand], nestedLayouts);
                included.add(cand);
                dirsWithLayouts.add(candDir);
                continue;
            }
            if (result.status === "rejected") {
                layoutLog.debug("stat nested tsx/jsx layout failed", result.reason);
            }
        }
    }
    catch (e) {
        layoutLog.debug("nested layout fallback scan failed", e);
    }
}
